// the player's own choice wins; otherwise the first browser language we have
function detect() {
  for (const l of navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en']) {
    const k = String(l).toLowerCase().split('-')[0]; if (STR[k]) return k;
  }
  return 'en';
}
let chosen = ''; try { chosen = localStorage.getItem('gobblelang') || ''; } catch (e) {}
const auto = detect();
let lang = STR[chosen] ? chosen : auto;

function t(key, vars) {
  let s = (STR[lang] && STR[lang][key]) ?? STR.en[key] ?? key;
  if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k]);
  return s;
}
// fill every element marked data-t (text), data-tp (placeholder) or data-ta (aria-label)
function apply(root) {
  root = root || document;
  document.documentElement.lang = lang;
  for (const el of root.querySelectorAll('[data-t]')) el.textContent = t(el.dataset.t);
  for (const el of root.querySelectorAll('[data-tp]')) el.placeholder = t(el.dataset.tp);
  for (const el of root.querySelectorAll('[data-ta]')) el.setAttribute('aria-label', t(el.dataset.ta));
}
function set(code) { // '' means automatic
  chosen = STR[code] ? code : ''; lang = chosen || auto;
  try { if (chosen) localStorage.setItem('gobblelang', chosen); else localStorage.removeItem('gobblelang'); } catch (e) {}
  apply();
}
window.I18N = { t, apply, set, langs: LANGS, get lang() { return lang; }, get chosen() { return chosen; }, get auto() { return auto; } };
